INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'e8668096-d0a8-53b6-86b6-0e3fbc305f06', 'e3f32e39-676f-53c5-aa3f-0596f9675703',
  'Implement three following hashing function:

```cpp
long int midSquare(long int seed);
long int moduloDivision(long int seed, long int mod);
long int digitExtraction(long int seed, int* extractDigits, int size);
```

Note that:

In `midSquare` function: we eliminate 2 last digits and get the 4 next digits.

In `digitExtraction`: `extractDigits` is a sorted array from smallest to largest index of digit in `seed` (index starts from 0). The array has size `size`.

**For example:**

| Test | Result |
| :--- | :--- |
| `int a[]={1,2,5};`<br>`cout << digitExtraction(122443,a,3);` | 223 |
| `cout <<midSquare(9452);` | 3403 |

Đáp án: ```cpp
long int midSquare(long int seed)
{
    long long sq = seed * seed;
    string str = to_string(sq);
    int size = str.size();
    string res = "";
    int cnt = 0;
    if (size-3 < 0) return 0;
    for (int i = size-3; i >= 0; --i)
    {
        res = str.substr(i,1) + res;
        ++cnt;
        if (cnt == 4) break;
    }
    return stol(res);
}
long int moduloDivision(long int seed, long int mod)
{
    return seed % mod;
}
long int digitExtraction(long int seed, int* extractDigits, int size)
{
    string str = to_string(seed);
    string res = "";
    for (int i = 0; i < size ; ++i)
    {
        int idx = extractDigits[i];
        res = res + str.substr(idx,1);
    }
    return stol(res);
}
```', 3
);

