  'b8da43d5-c9bd-51da-9b25-0466524a6e82', 'e3f32e39-676f-53c5-aa3f-0596f9675703',
  '### Implement Depth-first search

```cpp
Adjacency *DFS(int V);
```

where Adjacency is a structure to store list of number.

```cpp
#include <iostream>
#include <list>
using namespace std;

class Adjacency
{
private:
    list<int> adjList;
    int size;
public:
    Adjacency() {}
    Adjacency(int V) {}
    void push(int data)
    {
        adjList.push_back(data);
        size++;
    }
    void print()
    {
        for (auto const &i : adjList)
            cout << i << " -> " << i;
    }
    void printArray()
    {
        for (auto const &i : adjList)
            cout << i << " ";
    }
    int getSize() { return adjList.size(); }
    int getElement(int idx)
    {
        auto it = adjList.begin();
        advance(it, idx);
        return *it;
    }
};
```

And Graph is a structure to store a graph (see in your answer box)

### For example:

| Test | Result |
| :--- | :--- |
| `int V = 8, visited = 0;`<br>`Graph g(V);`<br>`Adjacency *arr;`<br>`int edge[][2] = {{0,1}, {0,2}, {0,3}, {0,4}, {1,2}, {2,5}, {2,6}, {4,6}, {6,7}};`<br>`for(int i = 0; i < 9; i++)`<br>`{`<br>`g.addEdge(edge[i][0], edge[i][1]);`<br>`}`<br>`// g.printGraph();`<br>`// cout << endl;`<br>`arr = g.DFS(visited);`<br>`arr->printArray();`<br>`delete arr;` | `0 1 2 5 6 4 7 3` |

Đáp án: ```cpp
class Graph
{
private:
    int V;
    Adjacency *adj;

public:
    Graph(int V)
    {
        this->V = V;
        adj = new Adjacency[V];
    }

    void addEdge(int v, int w)
    {
        adj[v].push(w);
        adj[w].push(v);
    }

    void printGraph()
    {
        for (int v = 0; v < V; ++v)
        {
            cout << "\nAdjacency list of vertex " << v << "\nhead ";
            adj[v].print();
        }
    }

    void DFS_help(bool* visited, Adjacency* test, int v )
    {
        visited[v] = true;
        test->push(v);
        int size = adj[v].getSize();
        for (int i = 0; i < size; ++i)
        {
            int ele = this->adj[v].getElement(i);
            if (!visited[ele]) DFS_help(visited, test, ele);
        }
    }

    Adjacency *DFS(int v)
    {
        bool* visited = new bool[this->V];
        for (int i = 0; i < this->V; ++i) visited[i] = false;
        Adjacency *test = new Adjacency(this->V);
        DFS_help(visited, test, v);
        return test;
    }
};
```', 5
);

